static void dist_cache_push(struct rar5* rar, int value) {
        int* q = rar->cstate.dist_cache;

        q[3] = q[2];
        q[2] = q[1];
        q[1] = q[0];
        q[0] = value;
}

static int dist_cache_touch(struct rar5* rar, int idx) {
        int* q = rar->cstate.dist_cache;
        int i, dist = q[idx];

        for(i = idx; i > 0; i--)
                q[i] = q[i - 1];

        q[0] = dist;
        return dist;
}

